{"path": "/tmp/sv-aa0ee20bfc8e44baa510041c46c935fa/Components/Chat/MessageItem.razor", "file_text": "<div class="message-item p-2 border-bottom position-relative"
     @onmouseenter="() => showActions = true"
     @onmouseleave="() => { showActions = true; showEmojiPicker = false; }">
    <div class="d-flex justify-content-between align-items-start">
        <div>
            <span class="fw-bold">@Message.Author</span>
            <small class="text-muted ms-2">@FormatRelativeTime(Message.SentAt)</small>
        </div>
        @if (showActions)
        {
            <div class="btn-group btn-group-sm">
                <button class="btn btn-outline-secondary btn-sm py-0 px-1"
                        title="Reply"
                        @onclick="HandleReply">
                    💬
                </button>
                <button class="btn btn-outline-secondary btn-sm py-0 px-1"
                        title="React"
                        @onclick="ToggleEmojiPicker">
                    😀
                </button>
            </div>
        }
    </div>

    <div class="mt-1">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="d-flex gap-1 mt-1 flex-wrap">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="btn btn-sm btn-outline-secondary py-0 px-1 reaction-badge"
                        @onclick="() => OnReact.InvokeAsync((Message.Id, reaction.Emoji))">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="btn btn-link btn-sm p-0 mt-1 text-decoration-none"
                @onclick="HandleReply">
            @ReplyCount replies
        </button>
    }

    @if (showEmojiPicker)
    {
        <div class="position-absolute bg-white border rounded shadow-sm p-1 d-flex gap-1"
             style="right: 0; top: -2rem; z-index: 10;">
            @foreach (var emoji in commonEmojis)
            {
                <button class="btn btn-sm btn-light py-0 px-1"
                        @onclick="() => SelectEmoji(emoji)">@emoji</button>
            }
        </div>
    }
</div>

@code {
    private bool showActions;
    private bool showEmojiPicker;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    [Parameter, EditorRequired] public required Services.Message Message { get; set; }
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task HandleReply() => await OnOpenThread.InvokeAsync(Message.Id);

    private async Task SelectEmoji(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}
"}

{"path": "/tmp/sv-aa0ee20bfc8e44baa510041c46c935fa/Components/Chat/ThreadPanel.razor", "file_text": "<div class="thread-panel d-flex flex-column h-100 border-start">
    <div class="p-3 border-bottom d-flex justify-content-between align-items-center">
        <h6 class="mb-0 fw-bold">Thread</h6>
        <button class="btn-close" @onclick="OnClose" aria-label="Close thread"></button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="p-2 border-bottom bg-light">
            <div class="fw-bold">@RootMessage.Author</div>
            <div class="text-muted small">@RootMessage.Content</div>
        </div>
    }

    <div class="overflow-auto flex-grow-1 p-2">
        @if (ThreadMessages is not null)
        {
            @foreach (var msg in ThreadMessages)
            {
                <MessageItem Message="msg"
                             ReplyCount="0"
                             OnReact="OnReact" />
            }
        }
    </div>

    <MessageInput Placeholder="Reply in thread…"
                  ButtonLabel="Reply"
                  OnSubmit="OnSendReply" />
</div>

@code {
    [Parameter] public Services.Message? RootMessage { get; set; }
