@* Reusable message input with textarea and submit button *@

<div class="message-input p-2 border-top">
    <div class="d-flex gap-2">
        <textarea class="form-control" rows="2"
                  placeholder="@Placeholder"
                  @bind="text"
                  @bind:event="oninput"
                  @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary align-self-end"
                disabled="@(string.IsNullOrWhiteSpace(text) || IsSending)"
                @onclick="Submit">
            @ButtonLabel
        </button>
    </div>
</div>

@code {
    private string text = string.Empty;
    private bool IsSending;

    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Submit();
        }
    }

    private async Task Submit()
    {
        if (string.IsNullOrWhiteSpace(text) || IsSending) return;
        IsSending = true;
        var message = text.Trim();
        text = string.Empty;
        await OnSubmit.InvokeAsync(message);
        IsSending = false;
    }
}

