toolArgs.file_text:
.chat-layout {
    display: flex;
    height: calc(100vh - 3.5rem);
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main-narrow {
    flex: 0 0 55%;
}

.chat-thread {
    width: 25%;
    min-width: 250px;
    flex-shrink: 0;
}

.message-list {
    flex: 1;
    overflow-y: auto;
}

::deep .message-item:hover {
    background-color: #f8f9fa;
}

::deep .reaction-badge {
    font-size: 0.8rem;
    line-height: 1;
}

::deep .message-input textarea {
    resize: none;
}

