 @page "/chat"
 @rendermode InteractiveServer
 @using sv_aa0ee20bfc8e44baa510041c46c935fa.Services
 @inject IChatService ChatService
 @inject IJSRuntime JS

 <PageTitle>Chat</PageTitle>

 <div class="chat-layout">
     <div class="chat-sidebar">
         <ChannelSidebar Channels="channels"
                         ActiveChannelId="selectedChannelId"
                         OnChannelSelected="SelectChannel" />
     </div>

     <div class="chat-main @(isThreadOpen ? "chat-main-narrow" : "")">
         @if (selectedChannel is not null)
         {
             <div class="p-3 border-bottom bg-white">
                 <h5 class="mb-0"># @selectedChannel.Name</h5>
                 <small class="text-muted">@selectedChannel.Description</small>
             </div>

             <div class="message-list overflow-auto flex-grow-1 p-2" @ref="messageListRef">
                 @if (isLoadingMore)
                 {
                     <div class="text-center p-2">
                         <div class="spinner-border spinner-border-sm" role="status">
                             <span class="visually-hidden">Loading…</span>
                         </div>
                     </div>
                 }

                 @foreach (var msg in messages)
                 {
                     <MessageItem Message="msg"
                                  ReplyCount="GetReplyCount(msg.Id)"
                                  OnOpenThread="OpenThread"
                                  OnReact="HandleReaction" />
                 }

                 @if (messages.Count == 0 && !isLoadingMore)
                 {
                     <div class="text-center text-muted p-4">No messages yet. Start the conversation!</div>
                 }
             </div>

             <MessageInput Placeholder="@($"Message #{selectedChannel.Name}")"
                           OnSubmit="SendMessage" />
         }
         else
         {
             <div class="d-flex align-items-center justify-content-center h-100 text-muted">
                 <div class="text-center">
                     <h4>Welcome to Chat</h4>
                     <p>Select a channel to get started</p>
                 </div>
             </div>
         }
     </div>

     @if (isThreadOpen)
     {
         <div class="chat-thread">
             <ThreadPanel RootMessage="threadRootMessage"
                          ThreadMessages="threadMessages"
                          OnClose="CloseThread"
                          OnSendReply="SendThreadReply"
                          OnReact="HandleReaction" />
         </div>
     }
 </div>

 @implements IAsyncDisposable

 @code {
     private List<Channel> channels = [];
     private List<Message> messages = [];
     private List<Message>? threadMessages;
     private Channel? selectedChannel;
     private int selectedChannelId;
     private Message? threadRootMessage;
     private bool isThreadOpen;
     private bool isLoadingMore;
     private bool hasMoreMessages = true;
     private const int PageSize = 30;
     private ElementReference messageListRef;
     private IJSObjectReference? jsModule;
     private DotNetObjectReference<Chat>? dotNetRef;

     // Track reply counts: rootMessageId -> count
     private Dictionary<int, int> replyCounts = new();

     protected override async Task OnInitializedAsync()
     {
         channels = await ChatService.GetChannelsAsync();
         if (channels.Count > 0)
         {
             await SelectChannel(channels[0].Id);
         }
     }

     protected override async Task OnAfterRenderAsync(bool firstRender)
     {
         if (firstRender)
         {
             jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                 "./Components/Pages/Chat.razor.js");
         }

         if (jsModule is not null && selectedChannel is not null)
         {
             dotNetRef ??= DotNetObjectReference.Create(this);
             await jsModule.InvokeVoidAsync("registerScrollHandler", messageListRef, dotNetRef);
         }
     }

     [JSInvokable]
     public async Task OnScrolledToTop()
     {
         if (isLoadingMore || !hasMoreMessages) return;
         await LoadMoreMessages();
         await InvokeAsync(StateHasChanged);
     }

     private async Task SelectChannel(int channelId)
     {
         selectedChannelId = channelId;
         selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
         messages = [];
         replyCounts = new();
         hasMoreMessages = true;
         isThreadOpen = false;
         threadRootMessage = null;
         threadMessages = null;

         var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
         messages = loaded;
         hasMoreMessages = loaded.Count == PageSize;
         BuildReplyCounts();

         await ChatService.MarkChannelReadAsync(channelId);

         // Update channel unread count locally
         var idx = channels.FindIndex(c => c.Id == channelId);
         if (idx >= 0)
         {
             channels[idx] = selectedChannel! with { UnreadCount = 0 };
             selectedChannel = channels[idx];
         }
     }

     private async Task SendMessage(string content)
     {
         if (selectedChannel is null) return;
         var msg = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
         messages.Add(msg);

         if (jsModule is not null)
         {
             await jsModule.InvokeVoidAsync("scrollToBottom", messageListRef);
         }
     }

     private async Task OpenThread(int messageId)
     {
         threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
         if (threadRootMessage is null) return;

         threadMessages = await ChatService.GetThreadAsync(messageId);
         isThreadOpen = true;
     }

     private void CloseThread()
     {
         isThreadOpen = false;
         threadRootMessage = null;
         threadMessages = null;
     }

     private async Task SendThreadReply(string content)
     {
         if (selectedChannel is null || threadRootMessage is null) return;
         var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
         threadMessages?.Add(reply);

         // Update reply count
         replyCounts[threadRootMessage.Id] = (replyCounts.GetValueOrDefault(threadRootMessage.Id)) + 1;
     }

     private async Task HandleReaction((int MessageId, string Emoji) args)
     {
         await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

         // Optimistically update UI
         UpdateReactionLocally(messages, args.MessageId, args.Emoji);
         if (threadMessages is not null)
         {
             UpdateReactionLocally(threadMessages, args.MessageId, args.Emoji);
         }
     }

     private static void UpdateReactionLocally(List<Message> messageList, int messageId, string emoji)
     {
         var idx = messageList.FindIndex(m => m.Id == messageId);
         if (idx < 0) return;

         var msg = messageList[idx];
         var reactions = msg.Reactions.ToList();
         var existing = reactions.FindIndex(r => r.Emoji == emoji);
         if (existing >= 0)
         {
             var r = reactions[existing];
             reactions[existing] = r with { Users = [..r.Users, "You"] };
         }
         else
         {
             reactions.Add(new Reaction(emoji, ["You"]));
         }
         messageList[idx] = msg with { Reactions = reactions };
     }

     private async Task LoadMoreMessages()
     {
         if (selectedChannel is null) return;
         isLoadingMore = true;
         StateHasChanged();

         var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
         if (older.Count < PageSize) hasMoreMessages = false;

         messages.InsertRange(0, older);
         BuildReplyCounts();
         isLoadingMore = false;
     }

     private void BuildReplyCounts()
     {
         // Count messages that are replies (have ReplyToId) grouped by root
         replyCounts = messages
             .Where(m => m.ReplyToId.HasValue)
             .GroupBy(m => m.ReplyToId!.Value)
             .ToDictionary(g => g.Key, g => g.Count());
     }

     private int GetReplyCount(int messageId) => replyCounts.GetValueOrDefault(messageId);

     public async ValueTask DisposeAsync()
     {
         if (jsModule is not null)
         {
             await jsModule.DisposeAsync();
         }
         dotNetRef?.Dispose();
     }
 }
